styles.css:
	.official-context {
	   --primary-colour: #000000;
	   --second-colour: ;
	}

	 .modal-header {
		 border: none;
	 }
	.official-context {
    --dark-nav-colour:#000;
    --dark-nav-colour-scroll:#000;
    --swiper-dark-arrow: #000;
    --border-radius: 30px;
     --radius: 15px;
    --border-width: 1px;
