}

nav.navbar .container-fluid {
    max-width: 1296px;
}

.hero-banner .container {
    bottom: 1rem;
    left: 50%;
    transform: translateX(-50%);
    color: white;
    z-index: 1;
}

.hero-banner-img {
    max-width: 1600px;
    margin: auto;
    display: block;
}

.hero-banner .bg-gradient {
    top: 0;
    height: 100%;
    width: 100%;
    position: absolute;
    background: linear-gradient(360deg, #0000008a, transparent 30%);
    z-index: 0;
    max-width: 1600px;
    left: 50%;
    transform: translateX(-50%);
}

@media(min-width: 1601px) {
    .hero-banner-img, .hero-banner .bg-gradient {
        border-radius: 15px;
    }
}

@media(max-width: 768px) {
    .hero-banner .bg-gradient {
        background: linear-gradient(360deg, #000000d9, transparent 55%);
    }
}

.official-context:has(.hero-banner-img) .navbar.navbar-dark {
    position: sticky;
    top: 0;
}

.hero-banner h1 {
    font-size: 2rem;
}

.hero-banner h2 {
    font-size: 1.8rem;
}

.card {
    border: none;
    border-radius: var(--radius);
}

.card.inpage {
    background-size: cover;
    background-position: center;
    height: 35svh;
    max-height: 400px;
    min-height: 300px;
    justify-content: end;
    border: none;
    overflow: hidden;
}

.inpage .bg-gradient {
