}

.footer .list-group-item {
    font-size: 14px;
}



ul.nav.mx-auto .nav-item {
    flex-direction: column;
}


/* nav effect */
.footer a, .footer a:hover {
    text-decoration: none;
}

nav .navbar-nav.mx-auto li.nav-item:after, nav .navbar-nav.mx-auto .show li.nav-link:after, .footer a:after {
    content: "";
    position: absolute;
    bottom: -2px;
    height: 3px;
    left: 0px;
    width: 30px;
    background-color: #000;
    border-radius: 0px 0px 0px 0px;
    transition: width .3s ease-in-out;
}

.dropdown-item:after {
    content: "";
    position: absolute;
    bottom: -2px;
    height: 3px;
    left: 1px;
    width: 30px;
    background-color: #000;
    border-radius: 0px 0px 0px 0px;
    transition: width .3s ease-in-out;
}

.footer a:after {
    left: 0px;
}

.navbar-nav.mx-auto li.nav-item:not(:hover):after, .footer a:not(:hover):after, .dropdown-item:not(:hover):after {
    width: 0px;
}

.navbar-nav.mx-auto .mega-menu .nav-item:has(.nav-link.active):after {
    width: 24px;
}


/* btn effect */
nav .nav-item.bubble {
    background: transparent;
    transition: all .3s ease-in-out;
    -webkit-mask-image: radial-gradient(#fff, #000);
    mask-image: radial-gradient(#fff, #000);
    white-space: nowrap;
    display: flex;
    position: relative;
    overflow: hidden;
}
nav .nav-item.bubble:hover {
    color: #fff !important;
    background-color: #000;
}

nav .nav-item.bubble:hover .nav-link {
    color: #fff !important;
}


nav .nav-item.bubble:after {
    content: "";
    position: absolute;
    left: -.10416667rem;
    top: 0;
    bottom: 0;
    width: 100%;
    background-color: #000;
    transition: all .3s ease-in-out;
    transform: translateX(-100%) translateZ(0);
    border-radius: 1.04166667rem;
    animation: none;
    opacity: 1;
    z-index: -1;
}


nav .nav-item.bubble:hover:after {
    transform: translateX(0) translateZ(0);
    left: 0;
}

nav .nav-item.bubble:hover:after {
    background-color: #000;
}



