#vertical-line {
    width: 1px;
    height: 150px;
}


.official-context {
    --dark-nav-colour: #000;
    --special-first: #323433;
    --special-second: #a59e8c;
}

.vy-scrolling .navbar.navbar-dark {
    border-bottom: 0.5px solid #e3e3e3;
}


.special-lettering {
    background: linear-gradient(90deg, var(--special-first), var(--special-second));
    background-clip: text;
    color: rgba(0, 0, 0, 0);
    font-weight: bold;
}

#side-menu {
    width: 100vw;
    right: -100vw;
    padding: 16px 16px;
}

.official-context.side-menu-visible #side-menu {
    transform: translateX(-100vw);
}

.img-fluid {
    border-radius: var(--border-radius);
}

#side-menu .navbar-brand {
    margin: -10px 0px 30px 30px;
    display: none;
}

#side-menu {
    z-index: 999;
    background: transparent !important;
}

#side-menu .nav-link {
    font-size: 18px;
}

.side-menu-overlay {
    z-index: 1;
    background: linear-gradient(130deg, rgba(0, 0, 0, 0.9) 0%, rgba(51, 51, 51, 0.9) 100%) !important;
}

#side-menu .contents {
    margin-top: 100px;
    overflow: scroll;
    height: calc(90vh - 140px);
}


#side-menu .bubble .nav-link:before {
    margin-right: 10px;
}

#side-menu:has(.dropdown.mega-menu) .nav-link {
    padding-left: 16px !important;
    padding-right: 16px !important;
}

#side-menu .close {
    margin-top: 18px;
    border-radius: var(--border-radius);
    font-weight: 100;
    margin-right: 0px;
}

#side-menu .mega-menu:not(.active) > .container {
    height: 0;
}

.navbar-dark .navbar-toggler {
    transition: opacity 0.8s ease, margin-right 0.8s ease;
}
.side-menu-visible .navbar-dark .navbar-toggler {
    opacity: 0;
    margin-right: -60px;
}

.side-menu-visible nav.navbar.navbar-dark {
    background: transparent !important;
    -webkit-backdrop-filter: none;
    backdrop-filter: none;
}

.side-menu-visible .nav-item:hover {
    background: none;
}

nav .navbar-nav.mx-auto li.nav-item:after, nav .navbar-nav.mx-auto .show li.nav-link:after, .footer a:after {
    height: 1px;
    background-color: #000;
}


.navbar.navbar-dark {
    position: fixed;
    top: 0px;
}

nav .nav-item.bubble:hover {
    color: #000 !important;
    background-color: #fff;
}

nav .nav-item.bubble:hover:after {
    background-color: #ffffff;
}

nav .nav-item.bubble:hover .nav-link {
    color: #000 !important;
}

