.mega-menu-open .navbar.navbar-dark {
    background: none !important;
    backdrop-filter: none !important;
}

.mega-menu {
    transition: opacity 0.8s ease, height 0.8s ease, margin-top 0.8s ease;
    height: calc(75svh + 10px);
    opacity: 1;
    position: fixed;
    padding-top: 40px;
    margin-top: 0px;
    width: 100%;
    left: 50%;
    transform: translateX(-50%);
    overflow-y: scroll;
}




.mega-menu-bg {
    transition: opacity 0.8s ease, height 0.8s ease, margin-top 0.8s ease;
    position: fixed;
    left: 0px;
    top: 0px;
    height: calc(75vh + 80px);
    width: 100vw;
    /* background: linear-gradient(130deg, rgba(0, 0, 0, 0.9) 0%, rgba(51, 51, 51, 0.9) 100%) !important; */
    background: linear-gradient(130deg, rgb(243 243 243 / 80%) 0%, rgb(248 248 248 / 88%) 100%) !important;
    z-index: -1;
    backdrop-filter: blur(10px) saturate(180%);
    -webkit-backdrop-filter: blur(10px) saturate(180%);
    border-bottom: 1px solid #f0f0f0;
}

.mega-menu:not(.active), .mega-menu-bg:not(.active) {
    height: 0px;
    opacity: 0;
    margin-top: 0px;
    z-index: -10;
    pointer-events: none;
}

ul.model-list {
    padding-left: 0;
    list-style: none;
}

.mega-menu-link {
    color: black;
    background: white;
    padding: .5rem .75rem;
    border-radius: 4px;
    padding: 1rem;
}

.mega-menu .nav-tabs {
    border-bottom: none;
}

.mega-menu .nav-tabs .nav-link {
    background: transparent;
    border: none;
}

.mega-menu .nav-tabs .nav-link:not(.active) {
    opacity: 0.5;
}

#side-menu .mega-link::before,
#side-menu .mega-link::after {
  content: "";
  position: absolute;
  width: 10px;
  height: 2px;
  background: currentColor;
  right: 0;
  top: 24px;
  transition: transform 0.3s ease;
}

#side-menu .mega-link::after {
  transform: rotate(90deg);
}

#side-menu .active .mega-link::after {
  transform: rotate(0deg) scaleX(0);
}

.hover-show {
    position: absolute;
    top: 30px;
    left: 0;
    width: 100%;
    background-color: transparent;
    border-radius: var(--radius);
    height: 100%;
    visibility: hidden;
    opacity: 0;
    transition: top .3s ease-in-out, opacity .3s ease-in-out, visibility .4s ease-in-out, background-color .5s ease-in-out;
}

.hover-show.active {
    top: 0;
    background-color: black;
    visibility: visible;
    opacity: 1;
}

ul.nav.mx-auto .nav-item:not(:last-child) a:not(.dropdown-item).card, ul.nav.mx-auto .nav-item:not(:last-child) a:not(.dropdown-item).btn-hollow {
    border-right: none;
}

.mega-menu .btn-hollow {
    font-size: .8rem;
}

.btn.btn-hollow.mega-menu-filter-option {
    background-color: white;
    color: black;
    white-space: nowrap;
}

.mega-menu .btn-hollow.btn-hollow-actions {
    font-size: 1rem;
    text-transform: capitalize;
    padding: .5rem 1rem;
    border-radius: var(--border-radius);
    background-color: white;
    color: black;
}

.btn-hollow.mega-menu-filter-option.active {
    background-color: black;
    color: white;
}

.model-list .card {
    background-color: white;
    /* background-color: #0000008a;*/
}

.mega-menu-filter::-webkit-scrollbar, .model-scroll-container::-webkit-scrollbar {
    display: none;
}

.mega-menu-filter, .model-scroll-container {
    -ms-overflow-style: none;
    scrollbar-width: none;
}

.model-scroll-container {
    height: calc(100% - 60px); 
    overflow-y: scroll; 
    overflow-x: hidden;
}

.model-card a.card {
    text-decoration: none;
}

.model-card img {
    transition: transform .4s ease-in-out;
}

.model-card:hover img {
    transform: scale(1.1);
}

@media(min-width: 992px) {
    .mega-menu {
        top: 70px;
    }

    .mega-menu.active {
        padding-bottom: 5rem;
    }
}

@media (min-width: 992px, max-width: 10124) {
    .mega-menu {
        left: 16px;
        top: 80px;
        min-width: calc(100vw - 32px);
    }
}

@media(max-width: 1200px) {
    .model-list .model-card .text-muted {
        line-height: 1.3;
        height: 35px;
    }
}

@media (max-width: 991px) {
    .mega-menu-bg {
        display: none;
    }


    #side-menu {
        padding-bottom: 5rem;
    }

    .mega-menu {
        height: unset;
        position: relative;
        margin-top: 0px;
        max-width: calc(100vw - 32px);
        max-height: unset;
        overflow: visible;
        margin-bottom: 20px;
        padding-top: 0px;
    }

    .mega-menu .model-list li.featured {
        height: 200px;
    }

    .mega-menu .model-list li.featured .model-list-item {
        justify-content: end;
    }

    .mega-menu .model-list li.card {
        height: 120px;
    }

    .mega-menu .model-list li.card .model-list-item {
        justify-content: center;
    }

    .mega-menu .model-list li.card img {
        max-height: 80px;
        object-fit: contain;
        position: absolute;
        right: 10px;
    }

    .mega-menu .model-list li .reserve-button {
        display: none;
    }

    .mega-menu-link {
        width: 100%;
        display: flex;
        justify-content: space-between;
    }

    .model-list-item-header .model-link {
        color: white;
    }

    .model-list-item-header .model-link i {
        vertical-align: middle;
        margin-left: 5px;
    }

    .mega-menu-filter {
        overflow-y: scroll;
    }

    #side-menu .nav-item:hover {
        background: transparent;
    }

    .mega-menu .container {
        padding: 0;
    }

    ul.nav.mx-auto .nav-item:not(:last-child) a:not(.dropdown-item) {
        border-right: none;
    }

    .navbar-brand {
        transition: margin .3s ease-in-out;
    }
}

@media(max-width: 768px) {
    .model-list .model-card .text-muted {
        font-size: .85rem;
        font-weight: 900;
    }
}

    /* no live */
    #side-menu {
        width: 1000px;
        background: transparent !important;
        overflow-y: hidden;
    }

    #side-menu .contents {
        margin-top: 100px;
        overflow-y: scroll;
        height: calc(95svh - 64px);
    }

    .side-menu-overlay {
        z-index: 1;
        background: linear-gradient(130deg, rgb(243 243 243 / 80%) 0%, rgb(248 248 248 / 88%) 100%) !important;
    }

