.hover-cta-container {
    bottom: -14rem;
    left: 50%;
    transform: translateX(-50%);
    z-index: 5;
    max-width: calc(100% - 1rem);
    transition: bottom .35s ease-in-out;
    -webkit-transition: bottom .35s ease-in-out;
}

.official-context.vy-scrolling .hover-cta-container {
    bottom: 1.25rem;
}

.official-context.side-menu-visible .hover-cta-container,
.official-context.mega-menu-open .hover-cta-container,
.official-context.virtual-dealer-open .hover-cta-container {
    bottom: -14rem;
}

.hover-cta {
    background-color: #eeededb8;
    backdrop-filter: blur(10px);
    -webkit-backdrop-filter: blur(10px);
}

.hover-cta .hover-cta-btn {
    display: inline-block;
    background: #fff;
    color: #000;
    border: 2px solid #fff;
    font-family: inherit;
    font-size: 1rem;
    font-weight: 600;
    line-height: 1.2;
    margin: 0;
    padding: clamp(.75rem, 1.6vw, 1rem) clamp(.875rem, 2.6vw, 1.75rem);
    cursor: pointer;
    transition: background-color .2s, color .2s, border-color .2s;
}

.hover-cta .hover-cta-btn:hover,
.hover-cta .hover-cta-btn:focus {
    background: #000;
    color: #fff;
    border-color: #000;
}

.hover-cta .hover-cta-btn:focus-visible {
    outline: 2px solid #000;
    outline-offset: 3px;
}

.hover-cta .hover-cta-btn-solid {
    background: #000;
    color: #fff;
    border-color: #000;
}

.hover-cta .hover-cta-btn-solid:hover,
.hover-cta .hover-cta-btn-solid:focus {
    background: #fff;
    color: #000;
    border-color: #fff;
}

/* Smallest phones: the three labels stop fitting on one line below this. */
@media (max-width: 359.98px) {
    .hover-cta .hover-cta-btn {
        font-size: .875rem;
        padding: .75rem .5rem;
    }
}

@media (prefers-reduced-motion: reduce) {
    .hover-cta-container {
        transition: none;
    }
}

.hover-cta-container .reserve-button {
    min-width: 180px;
}

@media(max-width: 600px) {
    .hover-cta-container .reserve-button {
        padding: 10px 20px;
        font-size: .9rem !important;
        min-width: fit-content;
    }
}

@media(max-width: 375px) {
    .hover-cta-container .reserve-button {
     font-size: .8rem;
     padding: 10px 15px;
    }
}
